css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::after { content: ''; position: absolute; z-index: 2; top: 22%; left: 28%; width: 36%; height: 48%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); clip-path: polygon(0 0, 0 84%, 24% 62%, 44% 100%, 62% 90%, 40% 54%, 76% 50%); animation: click-press calc(var(--loader-speed) * 1.8) ease-out infinite; }
.loader span { position: absolute; top: 58%; left: 38%; width: 22%; height: 22%; border-radius: 50%; border: calc(var(--loader-size) * .03) solid var(--accent-2); animation: click-ring calc(var(--loader-speed) * 1.8) ease-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .18); }
@keyframes click-press { 0%, 48% { transform: translate(0, 0); } 58% { transform: translate(6%, 8%) scale(.93); } 72%, 100% { transform: translate(0, 0); } }
@keyframes click-ring { 0%, 50% { opacity: 0; transform: scale(.3); } 60% { opacity: 1; } 100% { opacity: 0; transform: scale(2.1); } }
